import 'dart:convert';
import 'dart:math';

import 'package:flutter_test/flutter_test.dart';
import 'package:formbricks/src/common/config.dart';
import 'package:formbricks/src/common/logger.dart';
import 'package:formbricks/src/common/result.dart';
import 'package:formbricks/src/survey/action.dart';
import 'package:formbricks/src/survey/survey_store.dart';
import 'package:formbricks/src/types/errors.dart';
import 'package:formbricks/src/types/survey.dart';
import 'package:shared_preferences/shared_preferences.dart';

Map<String, dynamic> _surveyJson(
  String id,
  List<String> actionNames, {
  num? displayPercentage,
}) =>
    {
      'id': id,
      'triggers': [
        for (final name in actionNames)
          {
            'actionClass': {'name': name},
          },
      ],
      'languages': <dynamic>[],
      if (displayPercentage != null) 'displayPercentage': displayPercentage,
    };

/// Builds a persisted config. [filteredSurveys] defaults to [surveys].
String _configJson({
  List<Map<String, dynamic>> surveys = const [],
  List<Map<String, dynamic>>? filteredSurveys,
  List<Map<String, dynamic>> actionClasses = const [],
  String appUrl = 'https://app.formbricks.com',
}) =>
    jsonEncode({
      'workspaceId': 'wsp_1',
      'appUrl': appUrl,
      'workspace': {
        'expiresAt': '2100-01-01T00:00:00.000',
        'data': {
          'surveys': surveys,
          'actionClasses': actionClasses,
          'settings': <String, dynamic>{},
        },
      },
      'user': {'expiresAt': null, 'data': <String, dynamic>{}},
      'filteredSurveys': filteredSurveys ?? surveys,
      'status': {'value': 'success', 'expiresAt': null},
    });

/// A deterministic RNG: every [nextDouble] returns [value].
class _FixedRandom implements Random {
  _FixedRandom(this.value);

  final double value;

  @override
  double nextDouble() => value;

  @override
  int nextInt(int max) => 0;

  @override
  bool nextBool() => false;
}

Future<FormbricksConfig> _seed(String json) async {
  SharedPreferences.setMockInitialValues({FormbricksConfig.storageKey: json});
  FormbricksConfig.resetInstance();
  final config = FormbricksConfig.instance;
  await config.init();
  return config;
}

E _errOf<T, E>(Result<T, E> result) => switch (result) {
      Ok() => fail('expected Err'),
      Err(:final error) => error,
    };

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  setUp(() {
    Logger.resetInstance();
    SurveyStore.resetInstance();
  });

  group('track', () {
    test('unknown code → invalid_code, no survey set', () async {
      final config = await _seed(
        _configJson(
          actionClasses: [
            {'id': 'a', 'name': 'A', 'type': 'code', 'key': 'known'},
          ],
        ),
      );
      final result =
          await track('unknown', config: config, isConnected: () async => true);
      final error = _errOf(result);
      expect(error, isA<InvalidCodeError>());
      expect(error.code, FormbricksErrorCode.invalidCode);
      expect(SurveyStore.instance.survey, isNull);
    });

    test('offline → network_error with url + message, no survey set', () async {
      final config = await _seed(
        _configJson(
          actionClasses: [
            {'id': 'a', 'name': 'A', 'type': 'code', 'key': 'k'},
          ],
        ),
      );
      final result =
          await track('k', config: config, isConnected: () async => false);
      final error = _errOf(result) as NetworkError;
      expect(error.code, FormbricksErrorCode.networkError);
      expect(error.status, 0);
      expect(
        error.url.toString(),
        'https://app.formbricks.com/js/surveys.umd.cjs',
      );
      expect(error.message, contains('No internet connection'));
      expect(SurveyStore.instance.survey, isNull);
    });

    test('a throwing connectivity check is treated as offline', () async {
      final config = await _seed(
        _configJson(
          actionClasses: [
            {'id': 'a', 'name': 'A', 'type': 'code', 'key': 'k'},
          ],
        ),
      );
      final result = await track(
        'k',
        config: config,
        isConnected: () async => throw Exception('boom'),
      );
      expect(_errOf(result), isA<NetworkError>());
      expect(SurveyStore.instance.survey, isNull);
    });

    test('valid code + matching survey → ok, survey set', () async {
      final config = await _seed(
        _configJson(
          actionClasses: [
            {'id': 'a', 'name': 'ActName', 'type': 'code', 'key': 'mycode'},
          ],
          surveys: [
            _surveyJson('s1', ['ActName']),
          ],
        ),
      );
      final result =
          await track('mycode', config: config, isConnected: () async => true);
      expect(result.isOk, isTrue);
      expect(SurveyStore.instance.survey?.id, 's1');
    });

    test('valid code but no matching survey → ok, no survey set', () async {
      final config = await _seed(
        _configJson(
          actionClasses: [
            {'id': 'a', 'name': 'ActName', 'type': 'code', 'key': 'mycode'},
          ],
          surveys: [
            _surveyJson('s1', ['OtherAction']),
          ],
        ),
      );
      final result =
          await track('mycode', config: config, isConnected: () async => true);
      expect(result.isOk, isTrue);
      expect(SurveyStore.instance.survey, isNull);
    });

    test('only code-type action classes are matched', () async {
      final config = await _seed(
        _configJson(
          actionClasses: [
            {'id': 'a', 'name': 'A', 'type': 'noCode', 'key': 'mycode'},
          ],
        ),
      );
      final result =
          await track('mycode', config: config, isConnected: () async => true);
      expect(_errOf(result), isA<InvalidCodeError>());
    });

    test('a malformed action class is skipped; valid ones still match',
        () async {
      final config = await _seed(
        _configJson(
          actionClasses: [
            {'type': 'code', 'name': null},
            {'id': 'a', 'name': 'Good', 'type': 'code', 'key': 'good'},
          ],
        ),
      );
      final result =
          await track('good', config: config, isConnected: () async => true);
      expect(result.isOk, isTrue);
    });

    test('an unexpected internal error → internal_error', () async {
      // An uninitialized config makes `get()` throw, exercising the outer catch.
      FormbricksConfig.resetInstance();
      final result = await track(
        'x',
        config: FormbricksConfig.instance,
        isConnected: () async => true,
      );
      final error = _errOf(result) as InternalError;
      expect(error.code, FormbricksErrorCode.internalError);
      expect(error.operation, 'track');
      expect(error.cause, isA<StateError>());
    });
  });

  group('trackAction', () {
    test('matches across multiple triggers and surveys (last match wins)',
        () async {
      final config = await _seed(
        _configJson(
          surveys: [
            _surveyJson('s1', ['X', 'Target']),
            _surveyJson('s2', ['Target']),
          ],
        ),
      );
      final result = await trackAction('Target', config: config);
      expect(result.isOk, isTrue);
      expect(SurveyStore.instance.survey?.id, 's2');
    });

    test('no surveys → ok, logs, no survey set', () async {
      final config = await _seed(_configJson(surveys: const []));
      final result = await trackAction('Whatever', config: config);
      expect(result.isOk, isTrue);
      expect(SurveyStore.instance.survey, isNull);
    });

    test('a malformed survey entry is skipped; valid ones still match',
        () async {
      final config = await _seed(
        _configJson(
          filteredSurveys: [
            {'noId': true, 'triggers': <dynamic>[]},
            _surveyJson('good', ['Target']),
          ],
        ),
      );
      final result = await trackAction('Target', config: config);
      expect(result.isOk, isTrue);
      expect(SurveyStore.instance.survey?.id, 'good');
    });

    test('reads filteredSurveys — a raw workspace survey is not triggered',
        () async {
      final config = await _seed(
        _configJson(
          surveys: [
            _surveyJson('ineligible', ['Target']),
          ],
          filteredSurveys: const [],
        ),
      );
      final result = await trackAction('Target', config: config);
      expect(result.isOk, isTrue);
      expect(SurveyStore.instance.survey, isNull);
    });

    test('a filtered survey triggers even when absent from workspace surveys',
        () async {
      final config = await _seed(
        _configJson(
          surveys: const [],
          filteredSurveys: [
            _surveyJson('eligible', ['Target']),
          ],
        ),
      );
      final result = await trackAction('Target', config: config);
      expect(result.isOk, isTrue);
      expect(SurveyStore.instance.survey?.id, 'eligible');
    });

    test('threads the injected RNG into the percentage gate', () async {
      final config = await _seed(
        _configJson(
          filteredSurveys: [
            _surveyJson('s1', ['Target'], displayPercentage: 50),
          ],
        ),
      );

      var result = await trackAction(
        'Target',
        config: config,
        random: _FixedRandom(0.75),
      );
      expect(result.isOk, isTrue);
      expect(SurveyStore.instance.survey, isNull, reason: '75 ≥ 50 → skipped');

      result = await trackAction(
        'Target',
        config: config,
        random: _FixedRandom(0.25),
      );
      expect(result.isOk, isTrue);
      expect(SurveyStore.instance.survey?.id, 's1', reason: '25 < 50 → shown');
    });
  });

  group('triggerSurvey', () {
    test('sets the survey without a percentage gate', () {
      triggerSurvey(TSurvey.fromJson({'id': 'x'}));
      expect(SurveyStore.instance.survey?.id, 'x');
    });

    test('a roll below the displayPercentage sets the survey', () {
      triggerSurvey(
        TSurvey.fromJson({'id': 'x', 'displayPercentage': 50}),
        random: _FixedRandom(0.25),
      );
      expect(SurveyStore.instance.survey?.id, 'x');
    });

    test('a roll at/above the displayPercentage skips the survey', () {
      triggerSurvey(
        TSurvey.fromJson({'id': 'x', 'displayPercentage': 50}),
        random: _FixedRandom(0.5),
      );
      expect(SurveyStore.instance.survey, isNull);
    });

    test('a displayPercentage of 0 bypasses the gate entirely', () {
      triggerSurvey(
        TSurvey.fromJson({'id': 'x', 'displayPercentage': 0}),
        // A 0-roll would fail `0 < 0` if the gate ran.
        random: _FixedRandom(0),
      );
      expect(SurveyStore.instance.survey?.id, 'x');
    });

    test('a null displayPercentage always sets the survey', () {
      triggerSurvey(
        TSurvey.fromJson({'id': 'x'}),
        random: _FixedRandom(0.999),
      );
      expect(SurveyStore.instance.survey?.id, 'x');
    });
  });
}

import 'package:flutter_test/flutter_test.dart';
import 'package:formbricks/src/types/action_class.dart';

void main() {
  group('TActionClass', () {
    test('parses a code action', () {
      final a = TActionClass.fromJson({
        'id': 'a1',
        'name': 'Clicked',
        'type': 'code',
        'key': 'clicked',
      });
      expect(a.id, 'a1');
      expect(a.name, 'Clicked');
      expect(a.type, 'code');
      expect(a.key, 'clicked');
    });

    test('parses a noCode action with a null key', () {
      final a = TActionClass.fromJson({
        'id': 'a2',
        'name': 'PageView',
        'type': 'noCode',
        'key': null,
      });
      expect(a.type, 'noCode');
      expect(a.key, isNull);
    });

    test('tolerates missing optional id/type/key', () {
      final a = TActionClass.fromJson({'name': 'X'});
      expect(a.id, '');
      expect(a.type, '');
      expect(a.key, isNull);
      expect(a.name, 'X');
    });
  });
}

import 'dart:async';

import 'package:flutter_test/flutter_test.dart';
import 'package:formbricks/src/types/survey.dart';
import 'package:formbricks/src/user/interaction_refresh.dart';
import 'package:formbricks/src/user/update_queue.dart';

TSurvey _survey({
  TInteractionRefresh? interactionRefresh,
  String id = 'survey-a',
}) =>
    TSurvey(
      id: id,
      triggers: const [],
      languages: const [],
      delay: 0,
      interactionRefresh: interactionRefresh,
      raw: {'id': id},
    );

void main() {
  group('refreshSegmentsAfterInteraction', () {
    // The real queue is used so the production call path is exercised. Its
    // `pendingUserId` reports whether `updateUserId` was reached; the debounced
    // flush is cancelled in tearDown so no timer outlives the test.
    setUp(UpdateQueue.resetInstance);
    tearDown(UpdateQueue.resetInstance);

    test('no-ops for an anonymous user even when the gate is open', () {
      refreshSegmentsAfterInteraction(
        null,
        _survey(
          interactionRefresh: const TInteractionRefresh(
            onDisplay: true,
            onResponse: true,
            onFinished: true,
          ),
        ),
        InteractionSource.onDisplay,
      );

      expect(UpdateQueue.instance.isEmpty, isTrue);
    });

    test('no-ops for an empty user id', () {
      refreshSegmentsAfterInteraction(
        '',
        _survey(
          interactionRefresh: const TInteractionRefresh(onDisplay: true),
        ),
        InteractionSource.onDisplay,
      );

      expect(UpdateQueue.instance.isEmpty, isTrue);
    });

    test('no-ops when the gate is absent — no interaction targeting', () {
      refreshSegmentsAfterInteraction(
        'user-1',
        _survey(),
        InteractionSource.onDisplay,
      );

      expect(UpdateQueue.instance.isEmpty, isTrue);
    });

    test('no-ops when every flag is false', () {
      refreshSegmentsAfterInteraction(
        'user-1',
        _survey(interactionRefresh: const TInteractionRefresh()),
        InteractionSource.onDisplay,
      );

      expect(UpdateQueue.instance.isEmpty, isTrue);
    });

    test('no-ops when only a different source is flagged', () {
      refreshSegmentsAfterInteraction(
        'user-1',
        _survey(
          interactionRefresh: const TInteractionRefresh(onDisplay: true),
        ),
        InteractionSource.onResponse,
      );

      expect(UpdateQueue.instance.isEmpty, isTrue);
    });

    test('refreshes when the matching flag is set', () {
      for (final (source, gate) in [
        (
          InteractionSource.onDisplay,
          const TInteractionRefresh(onDisplay: true)
        ),
        (
          InteractionSource.onResponse,
          const TInteractionRefresh(onResponse: true)
        ),
        (
          InteractionSource.onFinished,
          const TInteractionRefresh(onFinished: true)
        ),
      ]) {
        UpdateQueue.resetInstance();
        refreshSegmentsAfterInteraction(
          'user-1',
          _survey(interactionRefresh: gate),
          source,
        );

        expect(UpdateQueue.instance.pendingUserId, 'user-1', reason: '$source');
      }
    });

    /// The flush is fire-and-forget, so an error on the returned future would otherwise
    /// surface as an unhandled async error and, in a test zone, fail the test.
    test('a failing flush does not escape as an unhandled async error',
        () async {
      final failures = <Object>[];

      await runZonedGuarded(
        () async {
          refreshSegmentsAfterInteraction(
            'user-1',
            _survey(
              interactionRefresh: const TInteractionRefresh(onDisplay: true),
            ),
            InteractionSource.onDisplay,
          );

          // Force the queued flush to fail: no appUrl/workspaceId is configured, so
          // `_flush` throws once the debounce elapses.
          await Future<void>.delayed(
            UpdateQueue.debounceDelay + const Duration(milliseconds: 100),
          );
        },
        (error, _) => failures.add(error),
      );

      expect(failures, isEmpty);
    });

    test('routes through the queue so a burst can coalesce', () {
      final survey = _survey(
        interactionRefresh: const TInteractionRefresh(
          onDisplay: true,
          onResponse: true,
          onFinished: true,
        ),
      );

      for (final source in InteractionSource.values) {
        refreshSegmentsAfterInteraction('user-1', survey, source);
      }

      // All three land in one pending batch; the queue's own 500 ms debounce is
      // what collapses them into a single request (covered by
      // update_queue_test.dart).
      expect(UpdateQueue.instance.pendingUserId, 'user-1');
    });
  });

  group('TInteractionRefresh.fromJson', () {
    test('reads all three flags', () {
      final gate = TInteractionRefresh.fromJson(const {
        'onDisplay': true,
        'onResponse': false,
        'onFinished': true,
      });

      expect(gate.shouldRefresh(InteractionSource.onDisplay), isTrue);
      expect(gate.shouldRefresh(InteractionSource.onResponse), isFalse);
      expect(gate.shouldRefresh(InteractionSource.onFinished), isTrue);
    });

    test('treats missing flags as false rather than failing', () {
      final gate = TInteractionRefresh.fromJson(const {'onDisplay': true});

      expect(gate.onDisplay, isTrue);
      expect(gate.onResponse, isFalse);
      expect(gate.onFinished, isFalse);
    });

    test('treats non-boolean flags as false', () {
      final gate = TInteractionRefresh.fromJson(const {
        'onDisplay': 'yes',
        'onResponse': 1,
        'onFinished': null,
      });

      expect(gate.onDisplay, isFalse);
      expect(gate.onResponse, isFalse);
      expect(gate.onFinished, isFalse);
    });

    test('ignores unknown keys', () {
      final gate = TInteractionRefresh.fromJson(const {
        'onDisplay': true,
        'onSomethingNew': true,
      });

      expect(gate.onDisplay, isTrue);
    });
  });

  group('TSurvey.interactionRefresh', () {
    test('is null when the workspace has no interaction targeting', () {
      expect(TSurvey.fromJson(const {'id': 'a'}).interactionRefresh, isNull);
    });

    test('is parsed when present', () {
      final survey = TSurvey.fromJson(const {
        'id': 'a',
        'interactionRefresh': {'onFinished': true},
      });

      expect(survey.interactionRefresh, isNotNull);
      expect(
        survey.interactionRefresh!.shouldRefresh(InteractionSource.onFinished),
        isTrue,
      );
    });

    /// Present-but-all-false is a real payload: the backend attaches it to every
    /// survey in an interaction-targeting workspace.
    test('all-false is present but never refreshes', () {
      final survey = TSurvey.fromJson(const {
        'id': 'a',
        'interactionRefresh': {
          'onDisplay': false,
          'onResponse': false,
          'onFinished': false,
        },
      });

      expect(survey.interactionRefresh, isNotNull);
      for (final source in InteractionSource.values) {
        expect(survey.interactionRefresh!.shouldRefresh(source), isFalse);
      }
    });

    test('a non-object value is ignored rather than throwing', () {
      expect(
        TSurvey.fromJson(const {'id': 'a', 'interactionRefresh': 'nope'})
            .interactionRefresh,
        isNull,
      );
    });

    /// The whole survey map is re-serialized into the WebView payload, so the
    /// gate has to survive the round trip for the runtime to see it.
    test('survives the raw round trip into the runtime payload', () {
      const json = {
        'id': 'a',
        'interactionRefresh': {'onDisplay': true},
      };

      expect(TSurvey.fromJson(json).toJson()['interactionRefresh'], {
        'onDisplay': true,
      });
    });
  });
}

import 'dart:convert';

import 'package:clock/clock.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:formbricks/src/common/config.dart';
import 'package:formbricks/src/common/logger.dart';
import 'package:formbricks/src/common/result.dart';
import 'package:formbricks/src/common/setup.dart' hide tearDown;
import 'package:formbricks/src/common/setup.dart' as fb_setup show tearDown;
import 'package:formbricks/src/types/config.dart';
import 'package:formbricks/src/types/errors.dart';
import 'package:http/http.dart' as http;
import 'package:http/testing.dart';
import 'package:shared_preferences/shared_preferences.dart';

const _appUrl = 'https://app.formbricks.com';
const _workspaceId = 'wsp_1';

String _envBody({List<Map<String, dynamic>> surveys = const []}) => jsonEncode({
      'data': {
        'expiresAt': '2100-01-01T00:00:00.000',
        'data': {
          'surveys': surveys,
          'actionClasses': <dynamic>[],
          'settings': <String, dynamic>{},
        },
      },
    });

Map<String, dynamic> _surveyJson(
  String id, {
  Map<String, dynamic>? segment,
}) =>
    {
      'id': id,
      'displayOption': 'respondMultiple',
      'triggers': <dynamic>[],
      'languages': <dynamic>[],
      if (segment != null) 'segment': segment,
    };

String _userBody({List<String> segments = const []}) => jsonEncode({
      'data': {
        'state': {
          'expiresAt': null,
          'data': {
            'userId': 'u1',
            'contactId': null,
            'segments': segments,
            'displays': <dynamic>[],
            'responses': <dynamic>[],
            'lastDisplayAt': null,
          },
        },
      },
    });

FormbricksError _errOf(Result<void, FormbricksError> r) => switch (r) {
      Ok() => fail('expected Err'),
      Err(:final error) => error,
    };

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  setUp(() {
    SharedPreferences.setMockInitialValues({});
    FormbricksConfig.resetInstance();
    Logger.resetInstance();
    resetSetupForTest();
  });

  test(
    'happy path returns Ok and persists config with empty filteredSurveys',
    () async {
      final mock = MockClient((_) async => http.Response(_envBody(), 200));

      final result = await setup(
        appUrl: _appUrl,
        workspaceId: _workspaceId,
        httpClient: mock,
        startTicker: false,
      );

      expect(result.isOk, isTrue);
      final config = FormbricksConfig.instance.get();
      expect(config.workspaceId, _workspaceId);
      expect(config.appUrl, _appUrl);
      expect(config.workspace, isNotNull);
      expect(config.filteredSurveys, isEmpty);
    },
  );

  test(
    'new-config setup populates filteredSurveys against the anonymous user',
    () async {
      final mock = MockClient(
        (_) async => http.Response(
          _envBody(
            surveys: [
              _surveyJson('eligible'),
              _surveyJson(
                'gated',
                segment: {'id': 'seg_a', 'hasFilters': true},
              ),
            ],
          ),
          200,
        ),
      );

      final result = await setup(
        appUrl: _appUrl,
        workspaceId: _workspaceId,
        httpClient: mock,
        startTicker: false,
      );

      expect(result.isOk, isTrue);
      final filtered = FormbricksConfig.instance.get().filteredSurveys;
      expect(
        filtered.map((e) => (e as Map)['id']).toList(),
        ['eligible'],
      );
    },
  );

  test(
    'matching-config sync recomputes filteredSurveys from the cache',
    () async {
      final now = DateTime(2026, 6, 1, 12);
      final cached = TConfig(
        workspaceId: _workspaceId,
        appUrl: _appUrl,
        workspace: TWorkspaceState(
          expiresAt: now.add(const Duration(hours: 1)),
          data: TWorkspaceData(
            surveys: [
              _surveyJson('eligible'),
              _surveyJson(
                'gated',
                segment: {'id': 'seg_a', 'hasFilters': true},
              ),
            ],
          ),
        ),
        // Stale empty set the sync must repopulate.
        filteredSurveys: const [],
        status: TStatus.success,
      );
      SharedPreferences.setMockInitialValues({
        FormbricksConfig.storageKey: jsonEncode(cached.toJson()),
      });
      FormbricksConfig.resetInstance();

      var calls = 0;
      final mock = MockClient((_) async {
        calls++;
        return http.Response(_envBody(), 200);
      });

      late Result<void, FormbricksError> result;
      await withClock(Clock.fixed(now), () async {
        result = await setup(
          appUrl: _appUrl,
          workspaceId: _workspaceId,
          httpClient: mock,
          startTicker: false,
        );
      });

      expect(result.isOk, isTrue);
      expect(calls, 0, reason: 'valid workspace + anonymous user → no HTTP');
      expect(
        FormbricksConfig.instance
            .get()
            .filteredSurveys
            .map((e) => (e as Map)['id'])
            .toList(),
        ['eligible'],
      );
    },
  );

  test(
    'matching-config sync filters against the backend-resolved user',
    () async {
      final now = DateTime(2026, 6, 1, 12);
      final cached = TConfig(
        workspaceId: _workspaceId,
        appUrl: _appUrl,
        workspace: TWorkspaceState(
          expiresAt: now.add(const Duration(hours: 1)),
